CREATE TABLE IF NOT EXISTS system_strategies (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,name TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active',horizon TEXT,assumptions JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS system_strategy_scenarios (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,strategy_id UUID NOT NULL,name TEXT NOT NULL,variables JSONB NOT NULL DEFAULT '{}'::jsonb,impact JSONB NOT NULL DEFAULT '{}'::jsonb,status TEXT NOT NULL DEFAULT 'draft',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS system_strategy_actions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,strategy_id UUID,scenario_id UUID,title TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'planned',priority INTEGER DEFAULT 50,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());